// THIN: shape only — real version lives in db::repo with tests
#[tauri::command]
fn good_save(state: tauri::State<'_, crate::state::AppState>, raw: String) -> Result<(), crate::error::AppError> {
    if raw.len() > 50_000 {
        return Err(crate::error::AppError::Validation(String::from("too long")));
    }
    let conn = state.db.lock().unwrap_or_else(|p| p.into_inner());
    crate::db::repo::save_setting(&conn, "raw", &raw)
}

