#[derive(serde::Serialize)]
pub struct Out { ok: bool }

pub fn save_item(item_id: String) -> Result<Out, String> {
    if item_id.is_empty() || item_id.len() > 100 {
        return Err(String::from("id must be 1..=100 chars"));
    }
    if !item_id.chars().all(|c| c.is_ascii_alphanumeric()) {
        return Err(String::from("id must be alphanumeric"));
    }
    let _ = std::fs::write(format!("./{item_id}.txt"), b"x");
    Ok(Out { ok: true })
}
